#!/usr/bin/env python3

"""
RoboMaster 哨兵导航与决策系统
第 8 课：比赛计时器

本课目标：

让 RobotState 中的 match_time
随着程序运行自动增加。

目前：

    health
        ↓
    从 /sentinel/health 获取

    x / y / yaw
        ↓
    暂时使用模拟数据

    match_time
        ↓
    由 ROS2 Timer 自动增加

注意：

这一课仍然是模拟比赛环境。

后面真正上车时，
match_time 可以替换成真实比赛系统提供的数据。
"""


# =====================================================
# 导入 ROS2
# =====================================================

import rclpy

from rclpy.node import Node


# =====================================================
# 导入血量消息
# =====================================================

from std_msgs.msg import Int32


# =====================================================
# RobotState
# =====================================================

class RobotState:

    """
    RobotState：

    保存机器人当前状态。

    当前包括：

        health
        x
        y
        yaw
        match_time
    """

    def __init__(self):

        # =============================================
        # 血量
        # =============================================

        self.health = 100


        # =============================================
        # X 坐标
        # =============================================

        self.x = 0.0


        # =============================================
        # Y 坐标
        # =============================================

        self.y = 0.0


        # =============================================
        # 机器人朝向
        # =============================================

        self.yaw = 0.0


        # =============================================
        # 比赛时间
        # =============================================

        # 比赛开始时：

        # 0 秒

        self.match_time = 0.0


# =====================================================
# RobotStateNode
# =====================================================

class RobotStateNode(Node):

    """
    RobotStateNode：

    ROS2 节点。

    负责：

        1. 接收血量
        2. 更新时间
        3. 打印 RobotState
    """

    def __init__(self):

        # =============================================
        # 初始化 ROS2 Node
        # =============================================

        super().__init__("robot_state_timer_node")


        # =============================================
        # 创建 RobotState
        # =============================================

        self.state = RobotState()


        # =============================================
        # 订阅血量
        # =============================================

        self.health_subscription = self.create_subscription(

            Int32,

            "/sentinel/health",

            self.health_callback,

            10
        )


        # =============================================
        # 创建比赛计时 Timer
        # =============================================

        # 每 1 秒执行一次 update_match_time()

        self.match_timer = self.create_timer(

            1.0,

            self.update_match_time
        )


        # =============================================
        # 创建状态打印 Timer
        # =============================================

        # 每 1 秒打印一次 RobotState。

        self.print_timer = self.create_timer(

            1.0,

            self.print_state
        )


        # =============================================
        # 启动提示
        # =============================================

        self.get_logger().info(

            "Robot State + Match Timer Start!"
        )


    # =================================================
    # 血量 Callback
    # =================================================

    def health_callback(self, msg):

        """
        接收到血量消息后：

            msg.data
                ↓
            state.health
        """

        self.state.health = msg.data


    # =================================================
    # 更新比赛时间
    # =================================================

    def update_match_time(self):

        """
        每次 Timer 触发：

            match_time + 1

        因为 Timer 设置为：

            1.0 秒

        所以：

            每秒增加 1。
        """

        self.state.match_time += 1.0


    # =================================================
    # 打印 RobotState
    # =================================================

    def print_state(self):

        """
        每秒打印一次当前状态。
        """

        self.get_logger().info(

            f"Health = {self.state.health}"
        )


        self.get_logger().info(

            f"Position = "
            f"X:{self.state.x}, "
            f"Y:{self.state.y}"
        )


        self.get_logger().info(

            f"Yaw = {self.state.yaw}"
        )


        self.get_logger().info(

            f"Match Time = "
            f"{self.state.match_time:.1f} s"
        )


# =====================================================
# main
# =====================================================

def main(args=None):

    # 初始化 ROS2
    rclpy.init(args=args)


    # 创建节点
    node = RobotStateNode()


    # 保持节点运行
    rclpy.spin(node)


    # 关闭 ROS2
    rclpy.shutdown()


# =====================================================
# 程序入口
# =====================================================

if __name__ == "__main__":

    main()